const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const headers = j.headers || {};
  const fromRaw = headers.from || j.From || '';
  const m = String(fromRaw).match(/<([^>]+)>/);
  const sender = (m ? m[1] : String(fromRaw)).trim();
  const subject = headers.subject || j.Subject || '';
  let body = String(j.textPlain || j.snippet || '');
  // drop quoted reply text and signatures
  const lines = [];
  for (const line of body.split(/\r?\n/)) {
    if (/^\s*>/.test(line) || /^On .+ wrote:\s*$/.test(line) || /^--\s*$/.test(line)) break;
    lines.push(line);
  }
  let question = lines.join('\n').trim();
  if (!question) question = subject.replace(/^\s*(question)\s*[:\-]?\s*/i, '').trim();
  out.push({ json: {
    question,
    sender_email: sender,
    email_subject: subject,
    message_id: j.id,
    thread_id: j.threadId
  }});
}
return out;

const q = $('Extract Question').first().json;
const docs = $input.all()
  .map(i => i.json && i.json.document)
  .filter(d => d && d.pageContent);

const context = docs.length
  ? docs.map((d, n) => {
      const md = d.metadata || {};
      return '[Chunk ' + (n + 1) + ' | file: ' + (md.filename || 'unknown') + ']\n' + d.pageContent;
    }).join('\n\n---\n\n')
  : '(No document context was retrieved from the knowledge base.)';

return [{ json: {
  question: q.question,
  context,
  chunks_retrieved: docs.length,
  sender_email: q.sender_email,
  email_subject: q.email_subject,
  message_id: q.message_id,
  thread_id: q.thread_id
}}];

